mkuse!{use crate :: ffi :: { CStr , CString , c_char } ;}
mkuse!{use crate :: ops :: Index ;}
mkuse!{use crate :: { fmt , mem , ptr } ;}
mkitem!{mkstruct!{# [doc = " Helper type to manage ownership of the strings within a C-style array."] # [doc = ""] # [doc = " This type manages an array of C-string pointers terminated by a null"] # [doc = " pointer. The pointer to the array (as returned by `as_ptr`) can be used as"] # [doc = " a value of `argv` or `environ`."] pub struct CStringArray { ptrs : Vec < * const c_char > , }}}
mkitem!{mkimpl!{impl CStringArray { # [doc = " Creates a new `CStringArray` with enough capacity to hold `capacity`"] # [doc = " strings."] pub fn with_capacity (capacity : usize) -> Self { let mut result = CStringArray { ptrs : Vec :: with_capacity (capacity + 1) } ; result . ptrs . push (ptr :: null ()) ; result } # [doc = " Replace the string at position `index`."] pub fn write (& mut self , index : usize , item : CString) { let argc = self . ptrs . len () - 1 ; let ptr = & mut self . ptrs [.. argc] [index] ; let old = mem :: replace (ptr , item . into_raw ()) ; drop (unsafe { CString :: from_raw (old . cast_mut ()) }) ; } # [doc = " Push an additional string to the array."] pub fn push (& mut self , item : CString) { let argc = self . ptrs . len () - 1 ; self . ptrs [argc] = item . into_raw () ; self . ptrs . push (ptr :: null ()) ; } # [doc = " Returns a pointer to the C-string array managed by this type."] pub fn as_ptr (& self) -> * const * const c_char { self . ptrs . as_ptr () } # [doc = " Returns an iterator over all `CStr`s contained in this array."] pub fn iter (& self) -> CStringIter < '_ > { CStringIter { iter : self . ptrs [.. self . ptrs . len () - 1] . iter () } } }}}
mkitem!{mkimpl!{impl Index < usize > for CStringArray { type Output = CStr ; fn index (& self , index : usize) -> & CStr { let ptr = self . ptrs [.. self . ptrs . len () - 1] [index] ; unsafe { CStr :: from_ptr (ptr) } } }}}
mkitem!{mkimpl!{impl fmt :: Debug for CStringArray { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_list () . entries (self . iter ()) . finish () } }}}
mkitem!{mkimpl!{unsafe impl Send for CStringArray { }}}
mkitem!{mkimpl!{unsafe impl Sync for CStringArray { }}}
mkitem!{mkimpl!{impl Drop for CStringArray { fn drop (& mut self) { self . ptrs [.. self . ptrs . len () - 1] . iter () . for_each (| & p | drop (unsafe { CString :: from_raw (p . cast_mut ()) })) } }}}
mkitem!{mkstruct!{# [doc = " An iterator over all `CStr`s contained in a `CStringArray`."] # [derive (Clone)] pub struct CStringIter < 'a > { iter : crate :: slice :: Iter < 'a , * const c_char > , }}}
mkitem!{mkimpl!{impl < 'a > Iterator for CStringIter < 'a > { type Item = & 'a CStr ; fn next (& mut self) -> Option < & 'a CStr > { self . iter . next () . map (| & p | unsafe { CStr :: from_ptr (p) }) } fn size_hint (& self) -> (usize , Option < usize >) { self . iter . size_hint () } }}}
mkitem!{mkimpl!{impl < 'a > ExactSizeIterator for CStringIter < 'a > { fn len (& self) -> usize { self . iter . len () } fn is_empty (& self) -> bool { self . iter . is_empty () } }}}